// Optional, lazily loaded sampled soundtrack. The original mixer still owns every SFX.
export class RemasteredMusic {
 constructor(context,{base=new URL('../assets/',import.meta.url),fetcher=(...a)=>fetch(...a),folder='music-remastered'}={}){if(!['music-remastered','music-orava'].includes(folder))throw Error('Invalid soundtrack folder');this.context=context;this.base=base;this.folder=folder;this.fetcher=fetcher;this.request=0;this.catalog=null;this.source=null;this.buffer=null;this.name=null;this.muted=false;this.output=context.createGain();this.output.connect(context.destination);}
 setMuted(value){this.muted=!!value;this.output.gain.setTargetAtTime(value?0:.75,this.context.currentTime,.008);}
 stop(){this.request++;this.abort?.abort();this.abort=null;const source=this.source;this.source=null;this.name=null;if(source){source.onended=()=>source.disconnect();try{source.stop();}catch{source.disconnect();}}}
 async loadCatalog(){if(!this.catalog)this.catalog=this.fetcher(new URL(this.folder+'/manifest.json',this.base)).then(async r=>{if(!r.ok)throw Error('Orchestral catalog unavailable');const m=await r.json();if(m.version!==1||!m.tracks)throw Error('Invalid orchestral catalog');return m;}).catch(e=>{this.catalog=null;throw e;});return this.catalog;}
 async play(name){
  if(!/^[A-Z0-9_-]+$/.test(name))throw Error('Invalid orchestral name');
  this.stop();const request=this.request,manifest=await this.loadCatalog();if(request!==this.request)return false;
  const entry=manifest.tracks[name];if(!entry||!new RegExp('^'+name+'\\.m4a$').test(entry.file)||!Number.isFinite(entry.loopStart)||!Number.isFinite(entry.loopEnd)||entry.loopStart<0||entry.loopEnd<=entry.loopStart)throw Error('Orchestral track unavailable');
  let buffer=this.buffer?.name===name?this.buffer.value:null;
  if(!buffer){const abort=this.abort=new AbortController();try{const response=await this.fetcher(new URL(this.folder+'/'+entry.file,this.base),{signal:abort.signal});if(!response.ok)throw Error('Orchestral audio unavailable');const bytes=await response.arrayBuffer();if(request!==this.request)return false;buffer=await this.context.decodeAudioData(bytes);if(request!==this.request)return false;if(buffer.duration<entry.loopEnd-.015)throw Error('Truncated orchestral audio');this.buffer={name,value:buffer};}catch(e){if(request!==this.request)return false;throw e;}finally{if(request===this.request)this.abort=null;}}
  if(request!==this.request)return false;const source=this.context.createBufferSource();source.buffer=buffer;source.loop=true;source.loopStart=entry.loopStart;source.loopEnd=Math.min(entry.loopEnd,buffer.duration);source.connect(this.output);source.onended=()=>source.disconnect();this.output.gain.cancelScheduledValues(this.context.currentTime);this.output.gain.setValueAtTime(0,this.context.currentTime);this.output.gain.linearRampToValueAtTime(this.muted?0:.75,this.context.currentTime+.035);source.start(this.context.currentTime+.01);this.source=source;this.name=name;return true;
 }
}
